interface I<T>
{
    T M();
}
class Base : I<(int a, int b)>
{
    public virtual (int a, int b) M() { return (1, 2); }
}
class Derived : Base, I<(int notA, int notB)>
{
    public override (int notA, int notB) M() { return (3, 4); }
}

